add_action( 'woocommerce_after_checkout_billing_form', 'perfectpixel_username_at_checkout' );
add_action( 'woocommerce_email_after_order_table', 'perfectpixel_username_in_email', 10, 2 );

function perfectpixel_username_at_checkout() {
	if ( is_user_logged_in() ) {
		echo '<p class="perfectpixel-username">' . esc_html( '{{username_checkout_label}}' ) . ' <strong>' . esc_html( wp_get_current_user()->user_login ) . '</strong></p>';
	}
}

function perfectpixel_username_in_email( $order, $sent_to_admin ) {
	$user = $order->get_user();
	if ( $user ) {
		echo '<p>' . esc_html( '{{username_email_label}}' ) . ' <strong>' . esc_html( $user->user_login ) . '</strong></p>';
	}
}
